mapper.select:
SELECT p.ticker, p.close_price AS previous_close, p.price_date AS previous_close_date FROM foreign_daily_close p JOIN ( SELECT ticker, MAX(price_date) AS price_date FROM foreign_daily_close WHERE price_date < #{asOf} AND ticker IN
#{ticker}
GROUP BY ticker ) latest ON latest.ticker = p.ticker AND latest.price_date = p.price_date ORDER BY p.ticker
